import json
import re

def _s(v):
    return '' if v is None else str(v).strip()

def _num(v):
    if isinstance(v, bool):
        return None
    if isinstance(v, (int, float)):
        try:
            return float(v)
        except Exception:
            return None
    t = _s(v).replace(' ', '')
    if not t:
        return None
    if ',' in t and '.' in t:
        if t.rfind(',') > t.rfind('.'):
            t = t.replace('.', '').replace(',', '.')
        else:
            t = t.replace(',', '')
    elif ',' in t:
        t = t.replace(',', '.')
    try:
        return float(t)
    except Exception:
        return None

def _fmt(v):
    n = _num(v)
    if n is None:
        return _s(v)
    try:
        s = '%.2f' % n
    except Exception:
        return _s(v)
    whole, _, frac = s.partition('.')
    neg = whole.startswith('-')
    if neg:
        whole = whole[1:]
    groups = []
    while len(whole) > 3:
        groups.insert(0, whole[-3:])
        whole = whole[:-3]
    groups.insert(0, whole or '0')
    out = '.'.join(groups) + ',' + frac
    return ('-' + out) if neg else out

def _true(v):
    return _s(v).lower() in ('true', '1', 'yes', 'evet', 'ok', 'success', 'dogru')

def _text(v):
    if isinstance(v, dict):
        for k in ('text', 'name', 'title', 'value', 'label', 'ad', 'adi'):
            if _s(v.get(k)):
                return _s(v.get(k))
        return ''
    if isinstance(v, list):
        return ', '.join(x for x in (_text(i) for i in v) if x)
    return _s(v)

def _walk(obj, prefix, out):
    if isinstance(obj, dict):
        for k in obj:
            kk = str(k)
            _walk(obj[k], (prefix + '.' + kk) if prefix else kk, out)
    elif isinstance(obj, list):
        i = 0
        while i < len(obj):
            _walk(obj[i], prefix, out)
            i += 1
    else:
        out.append((prefix.lower(), obj))

def _dicts(obj, out):
    if isinstance(obj, dict):
        out.append(obj)
        for k in obj:
            _dicts(obj[k], out)
    elif isinstance(obj, list):
        i = 0
        while i < len(obj):
            _dicts(obj[i], out)
            i += 1

def _dicts_of(obj):
    out = []
    try:
        _dicts(obj, out)
    except Exception:
        pass
    return out

