    if not t:
        return ''
    word = t.split()[-1]
    if len(word) == 4 and word.isdigit():
        word = DIGIT_WORDS.get(word[-1], '')
    low = word.lower()
    last_v = ''
    for ch in reversed(low):
        if ch in 'aeıioöuü':
            last_v = ch
            break
    harmony = {'a': 'ı', 'ı': 'ı', 'e': 'i', 'i': 'i', 'o': 'u', 'u': 'u',
               'ö': 'ü', 'ü': 'ü'}.get(last_v, 'i')
    tail = 'd' if (low and low[-1] not in 'fçhkpsşt') else 't'
    return "'" + tail + harmony + 'r'

