tools.pre_process_code:
try:
    _ALLOWED = {'Main menu': ['No eligible card', 'Nothing else wanted', 'Three tries used up', 'Wants another transaction mid-flow', 'Question outside this step', 'caller agrees to go', 'Not speaking Turkish', 'E-mail sent / declined', 'statement week changed / declined', 'Question outside this step, caller agrees to go', 'E-mail sent / declined, statement week changed / declined'], 'Call closed': ['Third silence'], 'Agent': ['Wants to pay / asks how or where to pay', 'Asks for an agent', 'Dispute / payment not showing', 'Still complaining after three calming replies', 'Card list or balance service fails', 'E-mail services fail', 'Statement week services fail'], 'IVR login step': ["Asking about someone else's card"]}
    _NO_REASON = ['promise', 'paid']
    _PROMISE_WINS = True
    _TRANSFER_WINS = False
    _TRANSFER_QUEUES = []
    _QUEUE_REASONS = {}
    _PAID_ALL = True
    _NOTES_OUTCOME = 'no_promise'

    def _s(v):
        return '' if v is None else str(v).strip()

    def _lc(v):
        return _s(v).lower()

    def _num(v):
        try:
            s = _s(v)
            return int(float(s)) if s else 0
        except Exception:
            return 0

    def _true(v):
        return _lc(v) in ('true', '1', 'yes', 'evet', 'ok', 'success')

    def _allowed(o):
        return [str(x) for x in (_ALLOWED.get(o) or [])]

    def _pair_ok(o, r):
        if o not in _ALLOWED:
            return False
        rs = _allowed(o)
        rl = _lc(r)
        if not rs:
            return rl in ('', 'none', 'null')
        return rl in [x.lower() for x in rs]

    def _pick(o, *prefs):
        rs = _allowed(o)
        for p in prefs:
            pl = _lc(p)
            for r in rs:
                if r.lower() == pl:
                    return r
        return rs[0] if len(rs) == 1 else None

    def _put(o, r):
        if not _pair_ok(o, r):
            return False
        b = config.get('body')
        if not isinstance(b, dict):
            b = {}
            config['body'] = b
        b['outcome'] = o
        if o in _NO_REASON or not _lc(r):
            b.pop('reason', None)
        else:
            b['reason'] = r
        return True

    def _notes():
        out = []
        seq = _s(vars.get('notes_seq'))
        if seq:
            for part in seq.split('|'):
                part = part.strip().lower()
                if part:
                    out.append(part)
        if not out:
            r = _lc(vars.get('add_note_args.reason'))
            if r:
                out.append(r)
        return out

    def _first_note(notes):
        for n in notes:
            if n != 'paid':
                return n
        return notes[0] if notes else None

    promised = _num(vars.get('create_promise_success_count')) > 0
    transfers = _num(vars.get('transfer_to_human_success_count'))
    queue = _s(vars.get('transfer_to_human_args.queue'))
    qlow = queue.lower()
    verified = (_true(vars.get('verify_identity_response.data.all_verified'))
                or _true(vars.get('verify_identity_response.data.verified')))
    wrong_left = _lc(vars.get('verify_identity_response.data.wrong_answers_left'))
    notes = _notes()

    def _transfer_reason():
        rs = _allowed('transferred')
        if not rs:
            return None
        mapped = _QUEUE_REASONS.get(qlow)
        if mapped and _lc(mapped) in [r.lower() for r in rs]:
            return mapped
        for r in rs:
            if r.lower() == qlow:
                return r
        return _pick('transferred')

    transfer_wins = transfers > 0 and (_TRANSFER_WINS or (qlow and qlow in [str(q).lower() for q in _TRANSFER_QUEUES]))
    done = False
    if promised and transfer_wins:
        done = _put('transferred', _transfer_reason())
    if not done and promised and _PROMISE_WINS:
        done = _put('promise', None)
    if not done and transfers > 0:
        done = _put('transferred', _transfer_reason())
    if not done and notes and _PAID_ALL and all(n == 'paid' for n in notes):
        done = _put('paid', None)
    if not done and notes:
        first = _first_note(notes)
        done = _put(_NOTES_OUTCOME, _pick(_NOTES_OUTCOME, first)) or _put(_NOTES_OUTCOME, first)
    if not done and not verified and wrong_left in ('0', '0.0'):
        done = _put('not_verified', _pick('not_verified', 'failed'))
    if not done and not verified and (_true(vars.get('identity_declined')) or _true(vars.get('declined'))):
        done = _put('not_verified', _pick('not_verified', 'declined'))
    if not done and ((_lc(vars.get('who_answers')) == 'deceased') or _true(vars.get('is_deceased')) or _true(vars.get('deceased')) or _lc(vars.get('situation')) == 'deceased'):
        done = _put('not_reached', _pick('not_reached', 'deceased'))
    if not done and ((_lc(vars.get('who_answers')) == 'wrong_number') or _true(vars.get('is_wrong_number')) or _true(vars.get('wrong_number')) or _lc(vars.get('situation')) == 'wrong_number'):
        done = _put('not_reached', _pick('not_reached', 'wrong_number'))
    if not done and _num(vars.get('schedule_callback_success_count')) > 0:
        done = _put('not_reached', _pick('not_reached', 'callback'))
    if not done and (_true(vars.get('callback_declined')) or _true(vars.get('no_callback')) or _lc(vars.get('situation')) == 'callback_refused'):
        done = _put('not_reached', _pick('not_reached', 'no_callback'))
    b = config.get('body')
    if isinstance(b, dict):
        o = _lc(b.get('outcome'))
        if o in _NO_REASON:
            b.pop('reason', None)
        elif o in _ALLOWED:
            rs = _allowed(o)
            if len(rs) == 1 and _lc(b.get('reason')) != _lc(rs[0]):
                b['reason'] = rs[0]
except Exception:
    pass
